  };

  // ---- 3. which topic a stored question measures --------------------------------------------------------------------------------------------
  const qWords = (p) => words([S(p.keyword), S(p.cluster), S(p.topic), S(p.focus_topic)].filter(Boolean).join(' ') || S(p.prompt));
