    const cap = Math.max(1, Math.floor((Math.round(n0(N)) - 1) / 2) - measured.length);
    const act = T('active').slice().sort((a, b) => hv(b.id) - hv(a.id) || (a.priority || 99) - (b.priority || 99) || S(b.started_at).localeCompare(S(a.started_at)));
    const core = T('core');
