    // with nothing active (the setup day) the services are the whole panel
    let coreN = core.length ? (act.length ? Math.max(Math.ceil(CFG.core_share * n0(N)) - 1, n0(N) >= 8 ? 2 : 1) : slots) : 0;
    coreN = Math.min(coreN, slots);
