      const fresh = z.state === 'active' && z.source !== 'service' && !!z.started_at && daysBetween(z.started_at, now) <= CFG.new_days && n0(have.get(z.id)) < CFG.min_per_topic;
      const isNew = fresh || !n0(have.get(z.id));
