    const byTopic = (list) => { const m = new Map(); for (const r of list) { const k = S(r.topic || r.label) || 'other'; m.set(k, n0(m.get(k)) + n0(r.count || 1)); } return [...m.entries()].map(([topic, n]) => ({ topic, n })); };
