      if (a) parts.push(a + ' question' + (a === 1 ? '' : 's') + ' added for ' + [...new Set(write.map(w => '"' + w.label + '"'))].join(', '));
      if (retire.length) parts.push(retire.length + ' retired (' + [...new Set(retire.map(r => r.reason))].slice(0, 2).join('; ') + '; their history is kept)');
